CREATE TABLE IF NOT EXISTS website_services (
    slug VARCHAR(80) PRIMARY KEY,
    content JSONB NOT NULL,
    is_published BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order INTEGER NOT NULL DEFAULT 0
);

